        viva2_keys=["Lack of joint attention (no pointing to show interest)", "Poor eye contact and failure to respond to name", "Repetitive stereotyped behaviors or insistence on sameness", "Regression of words or social milestones", "Formal Audiology testing first to exclude hearing impairment", "Referral to Child Development Programme (KKH/NUH CDU) and EIPIC"],
