        viva3_keys=["Eliminate/reduce toddler screen time (<2 years)", "Shared reading and face-to-face vocalization", "Reciprocal turn-taking games (peek-a-boo, rolling ball)", "Narrate daily activities with short phrases", "Early intervention before age 3 maximizes neurodevelopmental outcomes"],
